UPDATE products
SET stock = stock - 1
WHERE id = ? AND stock > 0;

UPDATE accounts
SET balance = balance - 100
WHERE id = ? AND balance >= 100;

UPDATE documents
SET body = ?, version = version + 1
WHERE id = ? AND version = ?;

BEGIN;
SELECT stock FROM products WHERE id = ? FOR UPDATE;
